window.kbPageData["views/practice/s-91888cb77ec12615"] = {"key":"practice/s-91888cb77ec12615","state":{"route":"practice/s-91888cb77ec12615"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\" open><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\" aria-current=\"page\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\"><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2025 地市级 申论#4":"8fa1ff87dd2f74eb2a379c63","江苏 2023 C类 申论#3":"8fa1ff87dd2f74eb2a379c63","江苏 2024 C类 申论#3":"8fa1ff87dd2f74eb2a379c63"},"questions":{"国考 2025 地市级 申论#4":{"paper":"国考 2025 地市级 申论","n":4,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",3]},"江苏 2023 C类 申论#3":{"paper":"江苏 2023 C类 申论","n":3,"mod":"申论","src":["22d3f6f8ead61f1ba343.pdf",4],"asrc":["65862c79cc2f34940f00.pdf",2]},"江苏 2024 C类 申论#3":{"paper":"江苏 2024 C类 申论","n":3,"mod":"申论","src":["a7cfdee83e6ff0de5e71.pdf",3],"asrc":["525cbf0b49bf46168baf.pdf",2]}},"first":{"qs":{"国考 2025 地市级 申论#4":{"paper":"国考 2025 地市级 申论","n":4,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",3],"m":["10925283eda035ea"],"task":"以S市政协委员的身份，根据材料4拟写助推“元科普”、促进科普与科研共发展的提案案由和建议，在500字内说明提案理由并提出可行措施。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所依据的科普政策发布于2022年，早于标注窗口。2024年论坛是材料中专家发言的来源，作答无需掌握论坛事件本身。"},"links":[{"id":"k-4332d00dc4b55e2d","label":"元科普的主体与内容","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"M1","quote":"它是对本领域科学前沿的清晰阐释、对相关知识由来的系统梳理","why":"元科普由一线科研领军人物或团队开展，阐释科学前沿、梳理知识由来、展望领域发展并传递科研亲历感悟，这决定了提案应动员哪些主体开展何种科普。","origin":"逐题标记"},{"id":"k-60c8c703ece7f41c","label":"科学普及与科技创新同等重要的政策要求","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"坚持把科学普及放在与科技创新同等重要的位置","why":"这一要求为提案纠正重科研轻科普的倾向提供政策依据。","origin":"逐题标记"},{"id":"k-79315705b1928158","label":"科研与科普通过公众双向交流相互促进","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"M1","quote":"公众的想法\n和需求及时进入到科学共同体的视野之中，成为推动科学发展的重要动力。","why":"科普促进公众理解科学和科研成果推广，公众的问题与需求又能启发科研，这为共发展提供理由并支撑双向交流建议。","origin":"逐题标记"},{"id":"k-a4244d8de187d316","label":"将科普纳入科研人员考核与激励","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"将科普工作作为激励、考核的重要指标","why":"将科普贡献纳入评价体系，有助于扭转重科研轻科普的倾向并提高科研人员的参与积极性。","origin":"逐题标记"},{"id":"k-ec829103d0d2cec7","label":"科研人员与科普工作者协作兼顾科学准确性和通俗性","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"兼顾精准表达和通俗易懂；与科普工作者做好配合，输出高质量科普内容。","why":"科研人员优先提供难以替代的一线专业解读，科普工作者协助转化表达，双方分工有助于提高产出质量。","origin":"逐题标记"},{"id":"k-593bbcc98a00861d","label":"科普内容由专业人员审核并由平台管控失实传播","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"发现虚假错误科普信息时，应立即采取措施，防止信息扩散。","why":"科普信息在多次转传中可能失真，专业审核可保障内容准确，平台可对热点传播及时监测和处置。","origin":"逐题标记"},{"id":"s-9f175b7eb1a79028","label":"用现实问题、政策依据和预期效益论证行动必要性","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"“案由”部分指出了当前社会对\n科普认知不足、国家关于科普的政策要求，以及“元科普”的意义。","why":"从分散材料中筛出问题、依据和效益，组织成解释为何要采取行动的完整理由。","origin":"逐题标记"},{"id":"s-91888cb77ec12615","label":"将材料中的问题和启示转化为明确主体与做法的建议","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"建议明确可行，条理清晰。","why":"把材料中的障碍和做法按议题归并，为每类问题写出由谁落实、如何落实的措施。","origin":"逐题标记"}],"stem":"假如你是S市政协委员，准备提交一份“关于助推‘元科普’，促进科普与科研共发展”的提案。请根据“给定资料4”，\n拟写“提案案由”和“建议”两部分的内容。（20分）\n要求：理由充分，建议明确可行，条理清晰。不超过500字。","options":[],"answer":"","analysis":"案由：当下，社会上还存在“重科研轻科普”的现象。但近年来，我国将科普重要性提到前所未有的高度，中央文\n件明确提出，“坚持把科学普及放在与科技创新同等重要的位置”。“元科普”恰能实现科研与科普互相促进。因此，要\n助推“元科普”，促进科普与科研共发展。\n  建议：\n  一、完善科普体制机制，提升科学家的科普积极性。全面释放科普的多维度功能，全维度建立科普评价体系，\n将科普工作作为激励、考核的重要指标；持续加强宣传，树立科学普及与科技创新同等重要的社会共识。\n  二、加强元科普队伍建设，提升科普产出质量。鼓励科学家优先将可支配的时间精力投身元科普，提升自身科\n普表述和写作能力，兼顾精准表达和通俗易懂；与科普工作者做好配合，输出高质量科普内容。\n  三、打破封闭的科学体系，促进科学家与公众双向交流。通过线下讲座、线上对话等交流方式，让科学知识、\n方法和思想普及到社会各层面，也让公众的想法和需求及时进入科学共同体视野，推动科学发展。\n  四、做好内容把关，避免虚假错误内容泛滥。科学家协助审核本领域的科普内容，确保准确性；网络平台加强\n监管，尤其重点关注热点话题，发现虚假错误科普信息时，应立即采取措施，防止信息扩散。\n  参考答案说明：本参考答案按照题干要求写到了“提案案由”和“建议”两部分内容。“案由”部分指出了当前社会对\n科普认知不足、国家关于科普的政策要求，以及“元科普”的意义。“建议”部分则从“完善科普体制机制，提升科学家的\n科普积极性”“加强元科普队伍建设，提升科普产出质量”“打破封闭的科学体系，促进科学家与公众双向交流”“做好内\n容把关，避免虚假错误内容泛滥”四个方面进行具体展开。各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["科技","公共管理"],"nature":"综合题","current":false},"江苏 2023 C类 申论#3":{"paper":"江苏 2023 C类 申论","n":3,"mod":"申论","src":["22d3f6f8ead61f1ba343.pdf",4],"asrc":["65862c79cc2f34940f00.pdf",2],"m":["88b9961a0a244d95"],"task":"以绿园社区青年干部小谭的身份，总结首届邻里创意集市的有效做法和居民反馈，提出办好第二届集市的具体可行建议。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答所需的集市做法和居民反馈均由材料给出，首届活动时间为2022年。"},"links":[{"id":"k-856cf9f6bc9bcc84","label":"社区活动提前开展多渠道宣传","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"利用社区广播、通告栏、微信公众号等多种渠道","why":"报名信息触达过晚时，提前通过线上线下渠道发布活动和招募信息，可以扩大居民知晓范围。","origin":"逐题标记"},{"id":"k-1340c15689b6d56a","label":"社区闲置物品交换的线上预发布与分龄参与","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"教会居民提前发布交换信息，吸引更多人参与","why":"线上预发布便于居民提前对接交换意向，分龄设置共享区可回应更多年龄段居民的参与需求。","origin":"逐题标记"},{"id":"k-beb9c16f5ed0628c","label":"按居民需求配置社区便民与志愿服务","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"量扩大志愿者队伍，并针对性满足特殊群体需求。","why":"居民反馈可用于筛选和丰富服务项目，排队情况与上门需求可用于调整志愿者数量和服务方式。","origin":"逐题标记"},{"id":"k-fdfd9f28c52e6107","label":"按咨询需求配置社区民政政策宣传资源","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"对社工进行民政政策培训，并增加咨询工作人员数量","why":"咨询集中、手册发放量大时，可培训社工、增配咨询人员，并依据上届发放情况估算手册用量。","origin":"逐题标记"},{"id":"k-75d75e6de6b6dc26","label":"社区微心愿捐款的用途公示与居民监督","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"公示捐款具体用途，并邀请社区居民","why":"公示捐款用途并引入居民代表监督，可以回应捐款人对资金去向的疑问。","origin":"逐题标记"},{"id":"s-91888cb77ec12615","label":"从活动成效和参与者反馈提炼改进对策","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"总结第一届邻里创意集市经验的基础上","why":"需要把首届成效转化为可延续的做法，把居民反馈转化为针对性改进措施。","origin":"逐题标记","originalId":"s-eafb324890408430"},{"id":"s-9b570af6b9f113ee","label":"按工作环节归并建议要点","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"五个方面进行了分条撰写","why":"将措施归入各自对应的工作环节，有助于形成并列且内容清晰的建议条目。","origin":"逐题标记","originalId":"s-d41ded17343b6fb1"}],"stem":"假如你是“给定资料6”中绿园社区的青年干部小谭，请你在总结第一届邻里创意集市经验的基础上，就如何办好第\n二届邻里创意集市提出建议。（20分）\n要求：全面具体，条理清晰，有针对性、可行性。篇幅350字左右。","options":[],"answer":"","analysis":"1.确保活动宣传到位。利用社区广播、通告栏、微信公众号等多种渠道，提前发布并广泛宣传活动的时间、地点\n和内容，让更多群众知晓集市活动信息。\n  2.争取群众广泛参与。传播社区数字化平台的使用方式，教会居民提前发布交换信息，吸引更多人参与；设置各\n年龄段的邻居共享区，让更多人有参与机会。\n  3.提高服务水平。收集群众意见，保留认可度高的特色服务，并进一步丰富类别；延续传统便民服务，根据需求\n量扩大志愿者队伍，并针对性满足特殊群体需求。\n  4.优化政策宣传。对社工进行民政政策培训，并增加咨询工作人员数量，提升咨询服务质量；根据上届情况评估\n宣传手册需求量，更好地满足群众咨询需求。\n  5.完善公益活动机制。保留微心愿公益捐款专区，全面收集困难居民心愿；公示捐款具体用途，并邀请社区居民\n代表监督捐款使用情况，提高居民的信任度。\n  参考答案说明：本参考答案从“活动宣传”“群众参与”“服务水平”“政策宣传”“公益活动”五个方面进行了分条撰写，\n各条答案要点之间在内容上相互并列，没有交叉。","figs":[],"state":"已标记","notes":[],"domains":["社会治理"],"nature":"综合题","current":false},"江苏 2024 C类 申论#3":{"paper":"江苏 2024 C类 申论","n":3,"mod":"申论","src":["a7cfdee83e6ff0de5e71.pdf",3],"asrc":["525cbf0b49bf46168baf.pdf",2],"m":["2af502be92f1c4fc"],"task":"以F村驻村第一书记小余的身份，代表村“两委”拟写一封约400字的公开信，说明退藕还稻的缘由，回应村民对种稻收益和复垦费用的担忧，并号召村民参与整改。","current_affairs":{"state":"否","event":null,"year":null,"basis":"材料已交代耕地保护和防止非粮化的政策要求，作答依靠材料中的政策与村情即可完成。"},"links":[{"id":"k-7710ae6ce7fdca2f","label":"耕地红线","catalog_id":"ac62f51740fec606","type":"制度与规则","role":"解题依据","field":"M1","quote":"牢牢守住十八亿亩耕地红线","why":"守住十八亿亩耕地红线是夯实粮食安全根基的政策要求，为说明F村退藕还稻的必要性提供依据。","origin":"逐题标记"},{"id":"k-f808cdc1f3231eb7","label":"稻渔综合种养可节省投入并增加亩均收益","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"节省农药、化肥等成本不说，收入也不低，每年亩产增收3000元左右。","why":"邻村种养实践表明，稻田兼养水产可节省农药和化肥投入，并增加亩均收益，为回应村民对种稻收益的担忧提供实例。","origin":"逐题标记"},{"id":"k-359fe1d28f029670","label":"适宜土壤上水稻与油菜轮作有助于保障产量和品质并提高土地生产能力","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"你们村的土壤非常适宜水稻油菜轮作，这样既能保证作物的产量和品\n质，又能提高土地生产能力。","why":"F村的土壤条件支持水稻与油菜轮作，为提出适合本村的复种方案提供依据。","origin":"逐题标记"},{"id":"s-91888cb77ec12615","label":"将群众顾虑与材料中的可行对策逐项对应","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"针对开头中村民不\n支持的原因，提出了相应的解决对策","why":"先识别影响村民参与的具体顾虑，再筛选相应的措施和案例来回应。","origin":"逐题标记","originalId":"s-0c5023cd3c3b3e1b"},{"id":"s-b92b682e65d12042","label":"按交代缘由、回应顾虑和发出号召组织动员内容","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"最后结尾部分再次强调主题，并发出呼吁号召。","why":"先向目标对象说明行动缘由，再用具体措施回应顾虑，最后提出清晰的行动号召。","origin":"逐题标记","originalId":"s-97bdaffa4bfa9ace"}],"stem":"假如你是“给定资料6”中的F村驻村第一书记小余，请以村“两委”的名义拟写一封致村民的公开信，动员村民退藕\n还稻。（25分）\n要求：主题明确，结构完整；有针对性，有感召力。篇幅400字左右。","options":[],"answer":"","analysis":"致F村村民的公开信\n各位村民朋友：\n  我村有3300亩基本农田，去年种藕现象蔓延，与国家政策相悖，急需退藕还粮。针对水稻收益低、复垦费用高\n等问题，也请乡亲们放心，一定会妥善解决。\n  一、创新种养模式，让种稻也能赚钱。我村会邀请农技专家推行“水稻+”种养模式，稻田里不止种水稻，还养禾\n花鱼、龙虾等，实现立体种养、一季多收，节约成本，根据邻村经验预计每亩增收3000元左右。\n  二、开展轮作种植，提供技术保障。我村土壤适宜水稻油菜轮作，镇里会与科研机构合作引进科技稻，同时推\n动有机绿色生产，获得有机认证证书，增加村民收入。\n  三、落实政府政策，提供资金补贴。村“两委”按照国家及县政府文件，积极帮助村民申请复垦补贴，降低损失。\n  粮食安全是国之大者，吃饭是第一大事，希望广大村民朋友积极支持退藕还稻工作！\n                                                      F村村两委\n                                                 XXXX年XX月XX日\n  参考答案说明：（1）格式方面，本参考答案写到了“标题”“称谓”“正文”“落款”四个部分。（2）正文部分，一方\n面，内容上，围绕“动员村民退藕还稻”这一主题，本参考答案的开头部分先交代F村推行退藕还稻的缘由、村民不支\n持的原因，并表明了坚决遏制耕地非粮化以及会妥善解决村民担忧的问题的态度；接着正文部分针对开头中村民不\n支持的原因，提出了相应的解决对策，以打消村民疑虑；最后结尾部分再次强调主题，并发出呼吁号召。另一方\n面，形式上，本参考答案做到了分段、分条撰写，整体上条理清晰，逻辑顺畅。最后，语言上，本参考答案做到了\n对象明确，通俗易懂，有感召力。","figs":[],"state":"待核","notes":["参考答案提出协助申请复垦补贴，材料只交代村民对复垦费用的担忧和县级工作方案的名称，补贴的设立及申请条件缺少材料依据。"],"domains":["社会治理","公共管理"],"nature":"综合题","current":false}},"materialFiles":{"10925283eda035ea":"d25a667f1b66e3f8cff8ceb7","88b9961a0a244d95":"7f6a27ee3f21695d99780659","2af502be92f1c4fc":"861cdbb496d071e4e3a8f22b"},"terms":{"k-4332d00dc4b55e2d":{"id":"k-4332d00dc4b55e2d","mode":"k","type":"概念与词义","title":"元科普","qs":[],"count":1},"k-60c8c703ece7f41c":{"id":"k-60c8c703ece7f41c","mode":"k","type":"制度与规则","title":"科学普及与科技创新同等重要","qs":[],"count":1},"k-79315705b1928158":{"id":"k-79315705b1928158","mode":"k","type":"原理与机制","title":"科研与科普的双向促进","qs":[],"count":1},"k-a4244d8de187d316":{"id":"k-a4244d8de187d316","mode":"k","type":"观点与论证","title":"将科普纳入科研人员考核与激励","qs":[],"count":1},"k-ec829103d0d2cec7":{"id":"k-ec829103d0d2cec7","mode":"k","type":"观点与论证","title":"科学家与科普工作者协作","qs":[],"count":1},"k-593bbcc98a00861d":{"id":"k-593bbcc98a00861d","mode":"k","type":"观点与论证","title":"科普内容审核与平台监管","qs":[],"count":1},"s-9f175b7eb1a79028":{"id":"s-9f175b7eb1a79028","mode":"s","type":"应用文写作","title":"陈述事由与请求","qs":[],"count":2},"s-91888cb77ec12615":{"id":"s-91888cb77ec12615","mode":"s","type":"提出对策","title":"从材料反馈中提炼改进建议","qs":[],"count":3},"k-856cf9f6bc9bcc84":{"id":"k-856cf9f6bc9bcc84","mode":"k","type":"观点与论证","title":"邻里创意集市的提前宣传","qs":[],"count":1},"k-1340c15689b6d56a":{"id":"k-1340c15689b6d56a","mode":"k","type":"观点与论证","title":"邻里创意集市的物品交换与分龄共享区","qs":[],"count":1},"k-beb9c16f5ed0628c":{"id":"k-beb9c16f5ed0628c","mode":"k","type":"观点与论证","title":"邻里创意集市的便民服务配置","qs":[],"count":1},"k-fdfd9f28c52e6107":{"id":"k-fdfd9f28c52e6107","mode":"k","type":"观点与论证","title":"邻里创意集市的民政政策咨询","qs":[],"count":1},"k-75d75e6de6b6dc26":{"id":"k-75d75e6de6b6dc26","mode":"k","type":"观点与论证","title":"微心愿捐款的用途公示与居民监督","qs":[],"count":1},"s-9b570af6b9f113ee":{"id":"s-9b570af6b9f113ee","mode":"s","type":"提出对策","title":"按治理环节组织对策","qs":[],"count":4},"k-7710ae6ce7fdca2f":{"id":"k-7710ae6ce7fdca2f","mode":"k","type":"制度与规则","title":"耕地保护红线","qs":[],"count":2},"k-f808cdc1f3231eb7":{"id":"k-f808cdc1f3231eb7","mode":"k","type":"原理与机制","title":"“水稻+”稻渔种养","qs":[],"count":1},"k-359fe1d28f029670":{"id":"k-359fe1d28f029670","mode":"k","type":"原理与机制","title":"水稻油菜轮作","qs":[],"count":1},"s-b92b682e65d12042":{"id":"s-b92b682e65d12042","mode":"s","type":"应用文写作","title":"面向公众动员参与","qs":[],"count":4}},"questions":{}},"firstMaterials":[{"key":"10925283eda035ea","value":["材料4","材料4\n  在大多数人看来，科学知识通常是采用特定技术方法获得的结果，其表达中含有许多专业术语，因此，科学知\n识对普通大众来说往往不容易理解。而关于科普，人们通常理解为单向的知识流动，即科普工作者把与日常生活相\n关的科学知识转换成通俗易懂的内容普及给大众。21世纪，科学进入到一个新的变革时期。科学界有识之士提出，\n需要打破封闭的科学体系，既要让科学知识、科学方法和科学思想充分地普及到社会各个层面，也要让公众的想法\n和需求及时进入到科学共同体的视野之中，成为推动科学发展的重要动力。\n  近年来，我国将科普的重要性提到了前所未有的高度。2022年9月，中共中央办公厅、国务院办公厅印发了《关\n于新时代进一步加强科学技术普及工作的意见》，提出要“坚持把科学普及放在与科技创新同等重要的位置”。\n  在科普产业化上海论坛上，我国某著名科普作家首次提出了“元科普”的概念。“元科普”是由工作在某个科研领域\n第一线的领军人物（或团队）进行的科普，它是对本领域科学前沿的清晰阐释、对相关知识由来的系统梳理、对该\n领域未来发展的理性展望，以及科学家亲身沉浸其中的独特感悟。如果把科普比作是一棵大树，那么“元科普”就是大\n树的根，为其它形形色色的科普作品提供坚实依据，它真实地传递了探索和创新过程中隐含着的科学精神。\n   “元科普”概念的提出再次引发人们关于科普应当普什么的思考。2024年7月30日，由S市科普作家协会主办的“助\n推‘元科普’，促进科学发展”论坛召开，多领域专家学者及科普工作者参加了论坛。以下是与会人员发言摘录。\n  甲：科普是科学家的天然使命，不能变成可做可不做的“副业”。从社会效益分析，它有助于提升国民科学素养水\n平和国家创新能力。从科学发展规律而言，它是科学发展的内生需求，只有公众理解科学，才能支持科学发展。我\n国拥有世界上最大规模的科研队伍，发表学术论文和申请专利数量位居世界前列，希望更多科学家投身科普事业，\n把科学普及真正落实到行动上。\n  乙：世界上其实已经诞生了不少“元科普”作品。比如，《物理学的进化》一书，是由爱因斯坦亲自来科普相对论\n和量子论，这是无人可以替代的。因为一个领域的创始者，才最明了这个思想究竟是怎么来的，这个理论是怎样建\n立的。当然，爱因斯坦也有一位难得的合作者——科普表述和写作能力极强的物理学家英费尔德。\n  丙：近年来，我国科普佳作接连问世。某著名海洋地质学家所著的《深海浅说》，从深海的基础知识，讲到深\n海的开发利用，既反映最新进展，又揭示科学发现的过程。再如，一线科学家所著的《生物学是什么》《进化史诗\n\n16讲》等都是精品。或有人问，科学家总是很忙的，又如何来做科普呢？那就是应该优先把有限的可支配时间与精\n力用来做别人难以替代的、潜在社会影响最大的“元科普”。\n  丁：重科研轻科普的现象一直都存在。科学家做科普，会担心被人贴上“不务正业”“好出风头”的标签，甚至有人\n认为“科研没啥成果才去做科普”。所以，“元科普”时代进入到科学传播的深水区，就要对科普的多维度功能进行全面\n释放，对科普评价体系进行全维度建立，使科学家心甘情愿做科普。\n  戊：有位奥地利物理学家曾开设了题为“生命是什么”的公开通俗讲座，听讲座的不仅有学者和研究人员，还有诸\n多社会人士。讲座结束后，该物理学家从非专业视角出发，把讲座内容写成了一本书《生命是什么》，使用通俗语\n言形象地探讨生命的特征。这本书的出版激发了当时众多物理学家和化学家进入生命科学研究领域，进而催生了分\n子生物学。\n   己：作为科普工作者，对有些科学内容把握不准，难免力不从心。在整个科学传播链中，科学家是无可替代\n的“第一发球员”。当然，还要有科普工作者作为“二传手”，这样才能唱好科学普及这台戏。此外，面对热点话题，必\n然会有二次传播、三次传播，其中有懂科学的，也有不懂科学的，可能就会变味。加之网络时代信息爆炸，伪科学\n等不良信息在网上传播快、影响大，所以如何监管也是面临的一个问题。\n  庚：我们利用玉米秸秆高效合成人造淀粉和单细胞蛋白质的新成果，正是缘于科普过程中公众困惑所带来的启\n示。就科研成果而言，也需要通过科普让公众有所了解，进而推广。这一过程中，如何寻求一个介于科学家对精准\n表达的要求和满足大众通俗易懂的要求之间的平衡点，进而获得受众群体的认同，也是非常重要的。\n  辛：科研和科普会不会冲突？时间分配上有冲突是必然的，但可以确定的是，科研和科普是一种正向的相互促\n进关系。或者说，“元科普”使科学研究与科学普及正朝着“你中有我，我中有你”的方向发展。",["16fbc0b81d8aafc9f70b.pdf",3]],"label":"国考 2025 地市级 申论|材料4"}],"node":{"id":"s-91888cb77ec12615","mode":"s","title":"从材料反馈中提炼改进建议","type":"提出对策","domain":"科技","reading":"","intro":"","priority":100,"aliases":["将材料中的问题和启示转化为明确主体与做法的建议","从活动成效和参与者反馈提炼改进对策","将群众顾虑与材料中的可行对策逐项对应"],"qs":["国考 2025 地市级 申论#4","江苏 2023 C类 申论#3","江苏 2024 C类 申论#3"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"从材料反馈中提炼改进建议","ids":["国考 2025 地市级 申论#4","江苏 2023 C类 申论#3","江苏 2024 C类 申论#3"],"units":[["国考 2025 地市级 申论#4"],["江苏 2023 C类 申论#3"],["江苏 2024 C类 申论#3"]]}]}};
